# ------------------------------------------------------------------
#  Scenario 1 figure: latitude distribution of the impact probability
#  and of the contribution to the casualty risk.
#
#  Reads the two HTML files generated by DRAMA-SARA and redraws the data.
#  Requires: matplotlib   (pip install matplotlib)
# ------------------------------------------------------------------
import json
from collections import defaultdict
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

# --- LATEX / TIMES NEW ROMAN CONFIGURATION ---
plt.rcParams["font.family"] = "serif"
plt.rcParams["font.serif"] = ["Times New Roman"]
plt.rcParams["mathtext.fontset"] = "stix"
plt.rcParams["font.size"] = 12
# --------------------------------------------------

# ERROR FIX: Use of double backslashes \\ in the Windows path
FOLDER = "C:\\Users\\salom\\OneDrive\\Documentos\\DRAMA\\MelpomeneSARAuncontrolled_Scenario1\\Results\\"
F_IMPACT   = "2026-08-29_09_36_10_default_1D_Imp_probability.html"
F_CASUALTY = "2026-08-29_09_36_15_default_1D_Casualty.html"
OUTPUT     = FOLDER + "s1_latitude_distribution"

BIN = 1        # width of the latitude intervals, in degrees
I_MAX = 81.8   # maximum reachable latitude, = 180 - inclination

# --- palette and ink ---------------------------------------------------
BLUE, ORANGE = "#2a78d6", "#eb6834"
INK, MUTED, GRID = "#2b2b28", "#52514e", "#e7e6e0"


def read_html(filename):
    """Extracts the x (latitude) and y vectors from the Plotly HTML."""
    s = open(FOLDER + filename, encoding="utf-8", errors="replace").read()
    i = s.find("plotly_data = ") + len("plotly_data = ")
    j = s.find("Plotly.react")
    d = json.loads(s[i:j].strip().rstrip(";").strip())["data"][0]
    return [float(v) for v in d["x"]], [float(v) for v in d["y"]]


def group(x, y, step=BIN):
    """Sums the values within each latitude interval."""
    acc = defaultdict(float)
    for xi, yi in zip(x, y):
        acc[round(xi // step) * step] += yi
    lats = sorted(acc)
    return lats, [acc[k] for k in lats]


lat_p, prob = group(*read_html(F_IMPACT))
lat_c, cas = group(*read_html(F_CASUALTY))
total = sum(cas)
band = sum(c for l, c in zip(lat_c, cas) if 20 <= l < 40)
north = sum(c for l, c in zip(lat_c, cas) if l >= 0)

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(6.4, 4.6), sharex=True,
                               gridspec_kw=dict(hspace=0.25))


def style(ax):
    ax.set_axisbelow(True)
    ax.grid(True, color=GRID, lw=0.6)
    for sp in ("top", "right"):
        ax.spines[sp].set_visible(False)
    for sp in ("left", "bottom"):
        ax.spines[sp].set_color("#9a988f")
        ax.spines[sp].set_linewidth(0.8)
    ax.tick_params(labelsize=12, colors=MUTED, length=3)


# --- (a) orbit geometry ---------------------------------------
style(ax1)
ax1.fill_between(lat_p, prob, color=BLUE, alpha=0.18, linewidth=0)
ax1.plot(lat_p, prob, color=BLUE, lw=1.6)
ax1.set_ylabel("Impact probability\nper degree", fontsize=12, color=INK)
ax1.set_ylim(0, max(prob) * 1.40)
# Font size of the (a) label reduced to 11
ax1.text(0, max(prob) * 1.28, "(a) where the satellite can fall",
         fontsize=11, color=INK, ha="center")
ax1.text(I_MAX - 5, max(prob) * 0.55, f"$\\pm{I_MAX}^{{\\circ}}$, set by\nthe inclination",
         fontsize=10.5, color=MUTED, ha="right")

# --- (b) risk ------------------------------------------------------
style(ax2)
ax2.fill_between(lat_c, cas, color=ORANGE, alpha=0.18, linewidth=0)
ax2.plot(lat_c, cas, color=ORANGE, lw=1.6)
ax2.set_ylabel("Contribution to $E_C$\nper degree", fontsize=12, color=INK)
ax2.set_xlabel("Latitude [deg]", fontsize=12, color=INK)
ax2.set_ylim(0, max(cas) * 1.40)
ax2.text(0, max(cas) * 1.28, "(b) where the casualty risk comes from",
         fontsize=11, color=INK, ha="center")
ax2.axvspan(20, 40, color=ORANGE, alpha=0.10, lw=0)
ax2.annotate(f"$20^{{\\circ}}$N to $40^{{\\circ}}$N:\n{100*band/total:.0f}% of $E_C$",
             xy=(30, max(cas) * 0.72), xytext=(-38, max(cas) * 0.88),
             fontsize=10.5, color=MUTED, ha="center",
             arrowprops=dict(arrowstyle="-", color="#9a988f", lw=0.7))

ax2.set_xlim(-88, 88)
ax2.set_xticks([-80, -60, -40, -20, 0, 20, 40, 60, 80])
fig.subplots_adjust(left=0.18, right=0.97, top=0.96, bottom=0.14)

# Save the files in your folder
fig.savefig(OUTPUT + ".pdf")
fig.savefig(OUTPUT + ".png", dpi=200)

print(f"E_C total           = {total:.4e}")
print(f"20N-40N             = {band:.4e}  ({100*band/total:.1f} %)")
print(f"northern hemisphere = {north:.4e}  ({100*north/total:.1f} %)")